(() => {
  const cardBtn = document.querySelector('button[class*="card"]');
  const res = [];
  document.querySelectorAll('span[title^="Bench Tester"]').forEach(e => {
    const cardAncestor = e.closest('button[class*="card"], [class*="card_"]');
    const modal = e.closest('[class*="Modal"], [class*="modal"]');
    res.push({title: e.getAttribute('title'), cls: e.className, inCardButton: !!cardAncestor, cardBtnText: cardAncestor ? cardAncestor.textContent.trim().slice(0,40) : null, inModal: !!modal});
  });
  return res;
})()

(() => {
  const out = {};
  const btns = Array.from(document.querySelectorAll('button')).filter(b=>b.textContent.trim().startsWith('hbpk3-n1'));
  out.cardButtons = btns.map(b=>({cls:b.className, titleAttr:b.getAttribute('title'), aria:b.getAttribute('aria-label'), txt:b.textContent.trim()}));
  const modal = document.querySelector('[class*="overlay"], [class*="Overlay"], [class*="Backdrop"]');
  out.overlayCls = modal ? modal.className : null;
  const parentOfMedium = document.querySelectorAll('span[title="Bench Tester"]')[3];
  out.mediumPath = [];
  let n = parentOfMedium;
  for (let i=0;i<6 && n;i++){ out.mediumPath.push(n.tagName + '.' + (n.className||'').toString().split(' ')[0]); n = n.parentElement; }
  return out;
})()
